package stickers

import (
	"math/rand"
	"strings"
	"time"
)

var (
	stickerRandom   = rand.New(rand.NewSource(time.Now().UnixNano()))
	sceneStickerMap = map[string][]string{
		"love": {
			"",
		},
		"greeting": {
			"",
		},
		"tsundere": {
			"",
		},
		"hungry": {
			"",
		},
		"panic": {
			"",
		},
	}
)

func getSceneSticker(scene string) string {
	list, ok := sceneStickerMap[scene]
	if !ok || len(list) == 0 {
		return ""
	}
	return list[stickerRandom.Intn(len(list))]
}

// DetectScene examines user input intent to match appropriate scene
func DetectScene(text string) string {
	lower := text
	// Love / Affection
	if containsAny(lower, "喜欢你", "爱你", "做我女朋友", "老婆", "抱抱", "亲亲", "么么哒", "永远在一起", "最喜欢", "贴贴") {
		return "love"
	}
	// Greeting
	if containsAny(lower, "你好", "早上好", "早安", "晚上好", "晚安", "在吗", "嗨", "hello", "hi", "ciallo") {
		return "greeting"
	}
	// Food / Hungry
	if containsAny(lower, "饿了", "吃白饭", "吃大餐", "吃什么", "干饭", "吃饭", "点外卖", "好饿", "投喂") {
		return "hungry"
	}
	// Tsundere / Overload
	if containsAny(lower, "笨蛋", "大肥鱼", "傻瓜", "过载", "死鱼眼", "晚期痴呆", "傲娇") {
		return "tsundere"
	}
	// Panic / Confusion
	if containsAny(lower, "救命", "怎么办", "完蛋了", "慌了", "宕机", "哭了", "呜呜") {
		return "panic"
	}
	return ""
}

func containsAny(s string, subs ...string) bool {
	for _, sub := range subs {
		if strings.Contains(s, sub) {
			return true
		}
	}
	return false
}

// GetRandomSceneSticker picks a verified embedded sticker for scene
func GetRandomSceneSticker(scene string) string {
	list, ok := sceneStickerMap[scene]
	if !ok || len(list) == 0 {
		return ""
	}
	return list[stickerRandom.Intn(len(list))]
}
